output_text:
[
  {
    "id": "no_cart_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfFlankedSingleFile": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_on_foot",
    "text": "An agent may enter a single-file aisle only when not pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": {
            "not": "singleFileAisle"
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "single_file_shelf_service_on_foot",
    "text": "Items on shelves in shelf-flanked single-file aisles must be picked without the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfFlankedSingleFile": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "shelfFlankedSingleFile"
        ]
      }
    }
  },
  {
    "id": "detach_only_at_aisle_mouth",
    "text": "A cart may be left behind only at designated wide aisle-mouth parking points.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cartParkingMouth": {
          "and": [
            "wideCrossAisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "detachCart": {
          "pre": "hasCart",
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "detachCart",
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "Whenever an agent parks or detaches from a cart, they must later reclaim a cart before finishing.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "detachCart": {
          "pre": "hasCart",
          "post": {
            "not": "hasCart"
          }
        },
        "reclaimCart": {
          "pre": {
            "not": "hasCart"
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "detachCart",
      "discharge": "reclaimCart"
    }
  },
  {
    "id": "open_shelf_interactions_need_cart",
    "text": "Interactions with open-aisle shelves must be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "openAisleShelf": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openAisleShelf",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_roaming_wide_store_without_cart",
    "text": "Except at the entrance/cart area or a cart-parking mouth, agents should not walk through wide store aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "entryOrCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedCartlessWidePlace": {
          "or": [
            "entryOrCartArea",
            "cartParkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          "wideAisle",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartlessWidePlace"
          }
        ]
      }
    }
  },
  {
    "id": "cart_traffic_no_west",
    "text": "Cart traffic follows a one-way convention in which agents pushing carts must not move west.",
    "abstraction": {
      "state_properties": {
        "cartTraffic": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartTraffic",
          "W"
        ]
      }
    }
  }
]
